def epoch(v) -> float:
    try:
        return float(datetime.fromisoformat(str(v).replace("Z", "+00:00")).timestamp())
    except (TypeError, ValueError):
        return math.nan


def iso(ts: float) -> str:
    return datetime.fromtimestamp(float(ts), UTC).strftime("%Y-%m-%dT%H:%M:%S.%fZ")


def now_ts() -> float:
    return datetime.now(UTC).timestamp()


def sha256_file(path: Path) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def git_commit() -> str:
    try:
        out = subprocess.run(["git", "rev-parse", "HEAD"], cwd=ROOT, capture_output=True, text=True, timeout=15)
        return out.stdout.strip()[:12] or "unknown"
    except (OSError, subprocess.SubprocessError):
        return "unknown"


def _json(o):
    if isinstance(o, (np.floating, np.integer)):
        v = o.item()
        return None if isinstance(v, float) and not math.isfinite(v) else v
    if isinstance(o, float) and not math.isfinite(o):
        return None
    if isinstance(o, np.bool_):
        return bool(o)
    if isinstance(o, np.ndarray):
        return o.tolist()
    return str(o)


def append_jsonl(path: Path, rows: list[dict]) -> None:
    if not rows:
        return
    path.parent.mkdir(parents=True, exist_ok=True)
    with open(path, "a", encoding="utf-8") as fh:
        for r in rows:
            fh.write(json.dumps(r, sort_keys=True, default=_json) + "\n")
        fh.flush()
        os.fsync(fh.fileno())


def dir_bytes(path: Path) -> int:
    tot = 0
    for p in Path(path).rglob("*"):
        if p.is_file():
            tot += p.stat().st_size
    return tot


def du_bytes(path: Path) -> int:
    try:
        out = subprocess.run(["du", "-sk", str(path)], capture_output=True, text=True, timeout=300)
        return int(out.stdout.split()[0]) * 1024
    except (OSError, subprocess.SubprocessError, ValueError, IndexError):
        return dir_bytes(path)


def _truthy(v: pd.Series) -> np.ndarray:
    return v.astype(str).str.strip().str.lower().isin(["true", "1", "1.0", "t"]).to_numpy()


def grid0(spec: dict) -> float:
    return epoch(spec["grid"]["grid0_utc"])


def slot_of(t: float, spec: dict) -> int | None:
    g0 = grid0(spec)
    k = int(round((t - g0) / GRID_S))
    return k if abs(t - (g0 + k * GRID_S)) <= SLOT_TOL_S else None


def slot_time(k: int, spec: dict) -> float:
    return grid0(spec) + k * GRID_S


def _manifest(path: Path) -> dict:
    return json.loads(Path(path).read_text())


class State:
    """Processed-id cache (``state.json``). Only a speed-up: the write-once files are the ground truth."""

    def __init__(self, root: Path) -> None:
        self.path = Path(root) / "state.json"
        self.d = json.loads(self.path.read_text()) if self.path.exists() else {}
        for k in ("captures", "samples", "sweeps"):
            self.d.setdefault(k, {})

    def save(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        tmp = self.path.with_suffix(".tmp")
        tmp.write_text(json.dumps(self.d, sort_keys=True))
        os.replace(tmp, self.path)


def scan_captures(snapshot_root: Path, st: State, spec: dict) -> dict[int, dict]:
    """Complete captures by slot ({slot: {"id", "start", "dir"}}); the first complete capture of a slot wins. Only a
    manifest that says ``state=complete`` counts (the collector renames it into place when the capture is done)."""
    for p in sorted(Path(snapshot_root).glob("*/manifest.json")):
        cid = p.parent.name
        if cid in st.d["captures"]:
            continue
        try:
            m = _manifest(p)
        except (OSError, ValueError):
            continue
        if m.get("state") != "complete" or not (p.parent / "rows.csv.gz").exists():
            continue
        t = epoch(m.get("started_utc"))
        st.d["captures"][cid] = {"start": t, "slot": slot_of(t, spec)}
    by_slot: dict[int, dict] = {}
    for cid, c in sorted(st.d["captures"].items(), key=lambda kv: kv[1]["start"]):
        if c["slot"] is None:
            continue
        by_slot.setdefault(c["slot"], {"id": cid, "start": c["start"], "dir": Path(snapshot_root) / cid})
    return by_slot


def scan_sweeps(sweep_root: Path, st: State) -> dict[str, dict]:
    """Sweep 1 (``series_index`` 0, state complete) by snapshot id ({snapshot_id: {"id", "dir"}})."""
    for p in sorted(Path(sweep_root).glob("*/manifest.json")):
        sid = p.parent.name
        if sid in st.d["sweeps"]:
            continue
        try:
            m = _manifest(p)
        except (OSError, ValueError):
            continue
        if m.get("state") != "complete" or not (p.parent / "rows.csv.gz").exists():
            continue
        st.d["sweeps"][sid] = {"snapshot_id": m.get("snapshot_id"), "series_index": m.get("series_index")}
    out: dict[str, dict] = {}
    for sid, s in sorted(st.d["sweeps"].items()):
        if s.get("series_index") == 0 and s.get("snapshot_id"):
            out.setdefault(s["snapshot_id"], {"id": sid, "dir": Path(sweep_root) / sid})
    return out


def fee_rates(ext: pd.DataFrame | None, market_ids: pd.Series) -> tuple[np.ndarray, np.ndarray]:
    """(taker fee rate, exponent) per market (``economics.fee_spec`` / ``resolve_rate``, policy max_if_unknown); an
    absent sidecar row resolves as unknown (the maximum documented rate)."""
    if ext is not None:
        e = ext.reindex(market_ids.astype(str))
    else:
        e = pd.DataFrame(index=market_ids.astype(str), columns=EXT_COLS[1:])
    key = e[["fee_schedule", "fees_enabled", "fee_category"]].astype(str)
    cache: dict = {}
    rate, expo = np.empty(len(key)), np.empty(len(key))
    for i, k in enumerate(key.itertuples(index=False)):
        k = tuple(k)
        if k not in cache:
            fs, fe, fc = (None if v in ("nan", "None", "") else v for v in k)
            s = economics.fee_spec(fs, fe, fc)
            cache[k] = (economics.resolve_rate(s, "max_if_unknown"), s.exponent)
        rate[i], expo[i] = cache[k]
    return rate, expo


def category_cols(ext: pd.DataFrame | None, market_ids: pd.Series, event_ids: pd.Series, spec: dict) -> dict:
    """sports (1/0, -1 = sidecar missing), crypto (1/0, -1), series-or-event key ``skey``, tick, created_ts."""
    n = len(market_ids)
    ev = event_ids.astype(str).to_numpy()
    if ext is None:
        return {"sports": np.full(n, -1), "crypto": np.full(n, -1), "skey": np.array(["event:" + e for e in ev], dtype=object),
                "tick": np.full(n, np.nan), "created_ts": np.full(n, np.nan)}
    e = ext.reindex(market_ids.astype(str))
    present = e["fee_type"].notna().to_numpy() | e["series_slugs"].notna().to_numpy() | e["created_at"].notna().to_numpy()
    ft, fc, ss = (e[c].where(e[c].notna(), None).tolist() for c in ("fee_type", "fee_category", "series_slugs"))
    cr = spec["crypto_rule"]
    rx = re.compile(cr["slug_regex"])
    sports, crypto, skey = np.empty(n, int), np.empty(n, int), np.empty(n, dtype=object)
    cache: dict = {}
    for i in range(n):
        key = (ft[i], fc[i], ss[i])
        if key not in cache:
            slug = lab.first_series_slug(ss[i])
            is_sp = cb17_census.is_sports_sidecar(ft[i], fc[i], ss[i])
            is_cr = str(ft[i] or "").lower().startswith(cr["fee_type_prefix"]) or bool(slug and rx.search(slug))
            cache[key] = (int(is_sp), int(is_cr), slug)
        sp, c, slug = cache[key]
        if not present[i]:
            sports[i], crypto[i], skey[i] = -1, -1, "event:" + ev[i]
            continue
        sports[i], crypto[i] = sp, c
        skey[i] = slug if slug else ("crypto:noslug" if c else "event:" + ev[i])
    tick = pd.to_numeric(e["order_price_min_tick_size"], errors="coerce").to_numpy(float)
    return {"sports": sports, "crypto": crypto, "skey": skey, "tick": tick, "created_ts": panel._epoch(e["created_at"])}


def series_frame(rows: pd.DataFrame, ext: pd.DataFrame | None, spec: dict) -> tuple[pd.DataFrame, pd.DataFrame]:
    """(series, status): two-sided quotes of open active binary markets, and the status of every other binary row
    (``closed_flag`` = closed true or active false; ``one_sided`` = open and active but not two-sided)."""
    b = rows[rows["binary"] == 1]
    closed = _truthy(b["closed"])
    active = _truthy(b["active"])
    two = panel.target_valid(b)
    ok = two & ~closed & active
    s = b[ok].reset_index(drop=True)
    bid, ask = s["best_bid"].to_numpy(float), s["best_ask"].to_numpy(float)
    spread = s["spread"].to_numpy(float)
    ltp = s["last_trade_price"].to_numpy(float)
    mids = s["market_id"].astype(str)
    cat = category_cols(ext, mids, s["event_id"], spec)
    rate, expo = fee_rates(ext, mids)
    ser = pd.DataFrame({
        "market_id": mids.to_numpy(), "event_id": s["event_id"].astype(str).to_numpy(), "t_row": s["t_row"].to_numpy(float),
        "bid": bid, "ask": ask, "spread": np.where(np.isnan(spread), ask - bid, spread),
        "ltp": np.where(ltp > 0, ltp, np.nan), "vol24": s["volume24hr"].to_numpy(float),
        "end_ts": panel._epoch(s["end_date"]), "created_ts": cat["created_ts"],
        "chg_1h": s["chg_1h"].to_numpy(float), "chg_1d": s["chg_1d"].to_numpy(float), "chg_1w": s["chg_1w"].to_numpy(float),
        "neg_risk": _truthy(s["neg_risk"]).astype(int), "sports": cat["sports"], "crypto": cat["crypto"], "skey": cat["skey"],
        "tick": cat["tick"], "fee_rate": rate, "fee_exp": expo,
    })
    nb = b[~ok]
    st = np.where(closed[~ok] | ~active[~ok], "closed_flag", "one_sided")
    status = pd.DataFrame({"market_id": nb["market_id"].astype(str).to_numpy(), "st": st})
    return ser, status


def read_series(root: Path, cap_id: str | None) -> pd.DataFrame | None:
    if cap_id is None:
        return None
    p = Path(root) / "series" / f"{cap_id}.csv.gz"
    if not p.exists():
        return None
    return pd.read_csv(p, dtype={"market_id": str, "event_id": str, "skey": str}).set_index("market_id")


def _look(ser: pd.DataFrame | None, mids, col: str) -> np.ndarray:
    if ser is None:
        return np.full(len(mids), np.nan)
    return ser[col].reindex(pd.Index(np.asarray(mids, dtype=str))).to_numpy(float)


def _mid(ser: pd.DataFrame | None, mids) -> np.ndarray:
    return (_look(ser, mids, "bid") + _look(ser, mids, "ask")) / 2.0


def tight_arr(bid, ask, spread, spread_max: float) -> np.ndarray:
    bid, ask, spread = (np.asarray(v, float) for v in (bid, ask, spread))
    with np.errstate(invalid="ignore"):
        return np.isfinite(bid) & np.isfinite(ask) & (bid > 0) & (bid < ask) & (ask <= 1) & (spread <= spread_max + 1e-12)


def classify(bid_p, ask_p, bid_k, ask_k, ltp_p, ltp_k, vol_p, vol_k, spec: dict) -> tuple[np.ndarray, np.ndarray]:
    """(class, geometry) of a k-1 -> k quote change (section 2 class rule; spec ``move``). Class: never_traded,
    traded, ambiguous, quote_only. Geometry (for every unit, traded ones included, for M3): parallel, one_sided,
    spread_change, same_side_unequal. Uses captures k - 1 and k only."""
    m = spec["move"]
    bid_p, ask_p, bid_k, ask_k, ltp_p, ltp_k, vol_p, vol_k = (np.asarray(v, float) for v in
                                                              (bid_p, ask_p, bid_k, ask_k, ltp_p, ltp_k, vol_p, vol_k))
    x = (bid_k + ask_k) / 2.0 - (bid_p + ask_p) / 2.0
    db, da = bid_k - bid_p, ask_k - ask_p
    hp, hk = np.isfinite(ltp_p), np.isfinite(ltp_k)
    with np.errstate(invalid="ignore"):
        L = (hp & hk & (np.abs(ltp_k - ltp_p) > m["ltp_tol"])) | (~hp & hk)
        dv = vol_k - vol_p
        vknown = np.isfinite(dv)
        vplus = vknown & (dv > m["vol_tol"])
        vzero = vknown & (np.abs(dv) <= m["vol_tol"])
    cls = np.where(~hp & ~hk, "never_traded",
                   np.where(L | vplus, "traded",
                            np.where(vzero & ~(hp & ~hk), "quote_only", "ambiguous")))
    sx, sb, sa = np.sign(x), np.sign(db), np.sign(da)
    adb, ada = np.abs(db), np.abs(da)
    with np.errstate(invalid="ignore"):
        par = (sb == sx) & (sa == sx) & (sx != 0) & (adb >= m["parallel_min"] - 1e-12) & (ada >= m["parallel_min"] - 1e-12) & (np.abs(db - da) <= m["parallel_max_diff"] + 1e-12)
        one = np.minimum(adb, ada) <= m["one_sided_max"] + 1e-12
        sprc = (sb * sa < 0) & (adb > m["one_sided_max"]) & (ada > m["one_sided_max"])
    geom = np.where(par, "parallel", np.where(one, "one_sided", np.where(sprc, "spread_change", "same_side_unequal")))
    return cls.astype(object), geom.astype(object)


def move_join(ser_k: pd.DataFrame, ser_p: pd.DataFrame, cap: dict, spec: dict, mid_lo: float, mid_hi: float,
              end_margin_h: float) -> tuple[pd.DataFrame, dict]:
    """Markets two-sided at k - 1 and k with the section 1.4 filters applied in order (each exclusion counted)."""
    sm = spec["eligibility"]["spread_max"]
    cnt = {"series_k": len(ser_k)}
    j = ser_k.join(ser_p[["bid", "ask", "spread", "ltp", "vol24"]].rename(columns=lambda c: c + "_p"), how="inner")
    cnt["not_two_sided_at_k_1"] = cnt["series_k"] - len(j)
    t = tight_arr(j["bid"], j["ask"], j["spread"], sm) & tight_arr(j["bid_p"], j["ask_p"], j["spread_p"], sm)
    cnt["not_tight"] = int((~t).sum())
    j = j[t]
    mid = (j["bid"].to_numpy(float) + j["ask"].to_numpy(float)) / 2.0
    band = (mid >= mid_lo) & (mid <= mid_hi)
    cnt["mid_band"] = int((~band).sum())
    j = j[band]
    end = j["end_ts"].to_numpy(float)
    with np.errstate(invalid="ignore"):
        eok = np.isnan(end) | (end > j["t_row"].to_numpy(float) + end_margin_h * 3600.0)
    cnt["end_date"] = int((~eok).sum())
    j = j[eok].copy()
    cnt["eligible"] = len(j)
    j.index.name = "market_id"
    return j.reset_index(), cnt


def token0_map(cap_dir: Path, mids: pd.Series) -> pd.Series:
    tok = pd.read_csv(forecast.require_local(Path(cap_dir) / "rows.csv.gz"), usecols=["market_id", "clob_token_id_0"],
                      dtype=str).drop_duplicates("market_id").set_index("market_id")["clob_token_id_0"]
    return tok.reindex(mids.astype(str))


def project_events(ids_day1: set, ids_all: set, n_days: int = 2, horizon_days: int = 21) -> float:
    """Distinct-event projection to 21 days (an estimate): E_2d + (E_2d - E_day1) x 19, the day-2 new-event rate carried
    forward (spec census_inputs.projection)."""
    e1, e2 = len(ids_day1), len(ids_all)
    return float(e2 + (e2 - e1) * (horizon_days - n_days))


def _days_of(by_slot: dict, days: list[str]) -> list[int]:
    return [k for k, c in sorted(by_slot.items()) if datetime.fromtimestamp(c["start"], UTC).strftime("%Y-%m-%d") in days]


def write_once_csv(path: Path, df: pd.DataFrame) -> bool:
    """Write ``df`` (gzip CSV, floats ``%.17g``: exact round trip, L1) to ``path`` only if it does not exist; atomic
    (tmp + hard link). False if it existed (the existing file is never touched)."""
    path = Path(path)
    if path.exists():
        return False
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_name(f".{path.name}.{os.getpid()}.tmp")
    df.to_csv(tmp, index=False, compression="gzip", float_format="%.17g")
    with open(tmp, "rb") as fh:
        os.fsync(fh.fileno())
    try:
        os.link(tmp, path)
    except FileExistsError:
        return False
    finally:
        tmp.unlink(missing_ok=True)
    return True


def sweep_frame(sweep_dir: Path, cap_dir: Path) -> pd.DataFrame:
    """Sweep 1 per market: the outcome-0 token's quote, receipt, two-sided flag, top sizes, 1c / 5c depths and min order
    size, plus the outcome-1 token's quote and 5c depths (the other token of the same market in the sweep; R1 finding 6)."""
    tok = pd.read_csv(forecast.require_local(Path(cap_dir) / "rows.csv.gz"), usecols=["market_id", "clob_token_id_0"],
                      dtype=str).drop_duplicates("market_id")
    sw = pd.read_csv(Path(sweep_dir) / "rows.csv.gz", usecols=lambda c: c in set(SWEEP_COLS), dtype={"token_id": str, "market_id": str})
    for c in SWEEP_COLS:
        if c not in sw:
            sw[c] = np.nan
    sw = sw.merge(tok, on="market_id", how="inner")
    t1 = sw[sw["token_id"] != sw["clob_token_id_0"]].drop_duplicates("market_id").set_index("market_id")
    sw = sw[sw["token_id"] == sw["clob_token_id_0"]].drop_duplicates("market_id")
    bid, ask = sw["best_bid"].to_numpy(float), sw["best_ask"].to_numpy(float)
    with np.errstate(invalid="ignore"):
        two = (bid > 0) & (ask > 0) & (ask <= 1) & (bid < ask)
    f = {c: pd.to_numeric(sw[c], errors="coerce").to_numpy(float) for c in SWEEP_COLS[6:]}
    o = t1.reindex(sw["market_id"].astype(str))
    g = {c: pd.to_numeric(o[c], errors="coerce").to_numpy(float) for c in ("best_bid", "best_ask", "depth_bid_5c", "depth_ask_5c")}
    return pd.DataFrame({"market_id": sw["market_id"].to_numpy(), "sbid": bid, "sask": ask,
                         "s_t": panel._epoch(sw["batch_receipt_utc"]), "s_two": two.astype(int),
                         "bsz1": f["bid_size_1"], "asz1": f["ask_size_1"], "dbid1": f["depth_bid_1c"], "dask1": f["depth_ask_1c"],
                         "dbid5": f["depth_bid_5c"], "dask5": f["depth_ask_5c"], "minord": f["min_order_size"],
                         "sbid_t1": g["best_bid"], "sask_t1": g["best_ask"], "dbid5_t1": g["depth_bid_5c"], "dask5_t1": g["depth_ask_5c"]})


def verify_files(seal: dict, files: list[tuple[str, Path]]) -> list[dict]:
    """[(archive path, local path)] against ``seal['files'][path]['sha256']``; a file missing locally, unsealed or with a
    different sha256 is returned as bad (L3: the census refuses)."""
    bad = []
    for rel, p in files:
        want = (seal.get("files", {}).get(rel) or {}).get("sha256")
        if not Path(p).exists():
            bad.append({"file": rel, "error": "missing"})
        elif want is None:
            bad.append({"file": rel, "error": "not sealed"})
        elif sha256_file(p) != want:
            bad.append({"file": rel, "error": "sha256 mismatch"})
    return bad


def capture_files(cap_dir: Path) -> list[tuple[str, Path]]:
    d = Path(cap_dir)
    out = [(f"data-dumps/research_lab/snapshots/{d.name}/{fn}", d / fn) for fn in ("rows.csv.gz", "manifest.json")]
    if (d / "rows_ext.csv.gz").exists():
        out.append((f"data-dumps/research_lab/snapshots/{d.name}/rows_ext.csv.gz", d / "rows_ext.csv.gz"))
    return out


def sweep_files(sweep_dir: Path) -> list[tuple[str, Path]]:
    d = Path(sweep_dir)
    return [(f"data-dumps/research_lab/book_sweeps/{d.name}/{fn}", d / fn) for fn in ("rows.csv.gz", "manifest.json")]


def _eff(df: pd.DataFrame, key: str = "market_id") -> pd.Series:
    """True for units in markets holding >= 2 units of the population (they survive the first-unit drop)."""
    n = df.groupby(key)[key].transform("size")
    return n >= 2


def _vif(df: pd.DataFrame, target: str, others: list[str]) -> float:
    """1 / (1 - R^2) of ``target`` on ``others`` (pooled OLS with intercept, finite rows only)."""
    d = df[[target, *others]].astype(float).replace([np.inf, -np.inf], np.nan).dropna()
    if len(d) < len(others) + 10:
        return float("nan")
    y = d[target].to_numpy()
    X = np.column_stack([np.ones(len(d)), d[others].to_numpy()])
    c, *_ = np.linalg.lstsq(X, y, rcond=None)
    r = y - X @ c
    tss = float(((y - y.mean()) ** 2).sum())
    if tss <= 0:
        return float("nan")
    r2 = 1.0 - float((r**2).sum()) / tss
    return float(1.0 / max(1.0 - r2, 1e-12))


def _ms(v) -> dict:
    v = np.asarray(v, float)
    v = v[np.isfinite(v)]
    if not len(v):
        return {"centre": None, "scale": None, "n": 0}
    return {"centre": float(np.mean(v)), "scale": float(np.std(v, ddof=1)) if len(v) > 1 else None, "n": int(len(v)),
            "terciles": [float(x) for x in np.quantile(v, [1 / 3, 2 / 3])]}


def _day(t) -> np.ndarray:
    return pd.to_datetime(np.asarray(t, float), unit="s", utc=True).strftime("%Y-%m-%d").to_numpy()


def design_effect(ev: pd.Series, scale: float, rho: float) -> dict:
    """Census-computed event design effect (R1 finding 8): m = sum n_e^2 / sum n_e on the census days, projected to 21 days
    as m x scale (pessimistic: every event recurs through the window), DE = 1 + (m_21 - 1) rho."""
    n = ev.value_counts().to_numpy(float)
    m = float((n**2).sum() / n.sum()) if len(n) else float("nan")
    m21 = m * scale
    return {"m_census": m, "m_21d": m21, "rho": rho, "DE": 1.0 + (m21 - 1.0) * rho if np.isfinite(m21) else float("nan")}


def block_anchor(spec: dict, census_days: list[str] | None = None) -> float:
    """UTC-midnight anchor of two-day blocks (R2 finding 10 and re-check finding 2), one rule for census and analysis.
    Analysis (``census_days`` None): REGISTERED_UTC, asserted to be a UTC midnight. Census: the first of that census's own
    UTC days (``YYYY-MM-DD`` or ``YYYYMMDD``), a UTC midnight at an even (zero) offset from itself, so that consecutive
    census days pair into one block (CQ/CH 10-15/10-16 and CF 10-16/10-17 each form one block). Both are even-offset UTC
    midnights: block = floor(day offset / 2) in ``perm_share`` and ``analysis.block_of``."""
    if census_days:
        d = min(str(x).replace("-", "") for x in census_days)
        t = epoch(f"{d[:4]}-{d[4:6]}-{d[6:8]}T00:00:00Z")
    else:
        t = epoch(spec["registered_utc"])
        assert t % 86400.0 == 0.0, "REGISTERED_UTC must be a UTC midnight"
    return t


def de_gate(de: dict, floor: float) -> float:
    """DE used by a census gate: max(floor, computed) (R2 finding 4: rho 0.02 is an example, not an estimate, so the
    computed DE may not loosen R0's 3.0)."""
    return float(max(floor, de["DE"])) if np.isfinite(de["DE"]) else float("nan")


def _family_rule(pop: pd.DataFrame, cap: float) -> tuple[pd.DataFrame, str, float | None]:
    """Answer 9 (R1): if the top series family holds > ``cap`` of the population, it is excluded from the primary."""
    fam = pop["skey"].astype(str).value_counts()
    top = float(fam.iloc[0] / fam.sum()) if len(fam) else None
    if top is not None and top > cap:
        return pop[pop["skey"].astype(str) != fam.index[0]], str(fam.index[0]), top
    return pop, "", top


def _gate(d: dict) -> dict:
    d["pass"] = all(d.values())
    return d


def cleanup_census(work: Path) -> None:
    shutil.rmtree(work, ignore_errors=True)


def demean(df: pd.DataFrame, cols: list[str], group: str, order: str, estimator: str) -> pd.DataFrame:
    X = df[cols].astype(float)
    if estimator == "expanding":
        return bd.expanding_demean(pd.concat([X, df[[group, order]]], axis=1), cols, group, order)[cols]
    if estimator == "fe":
        return X - X.groupby(df[group].to_numpy()).transform("mean")
    return X


def _partial(Z: np.ndarray, v: np.ndarray) -> np.ndarray:
    Z1 = np.column_stack([np.ones(len(v)), Z]) if Z.size else np.ones((len(v), 1))
    c, *_ = np.linalg.lstsq(Z1, v, rcond=None)
    return v - Z1 @ c


def wcorr(df: pd.DataFrame, a: str, c: str) -> dict:
    """Pooled and within-market (expanding-past demeaned, the estimator's own variation) correlations of two columns."""
    d = df[["market_id", "t_row", a, c]].replace([np.inf, -np.inf], np.nan).dropna()
    out = {"pooled": None, "within": None, "n": len(d)}
    if len(d) < 10:
        return out
    if d[a].astype(float).std() > 0 and d[c].astype(float).std() > 0:
        out["pooled"] = float(np.corrcoef(d[a].astype(float), d[c].astype(float))[0, 1])
    X = demean(d, [a, c], "market_id", "t_row", "expanding")
    X = X.replace([np.inf, -np.inf], np.nan).dropna()
    if len(X) >= 10 and X[a].std() > 0 and X[c].std() > 0:
        out["within"] = float(np.corrcoef(X[a], X[c])[0, 1])
    return out


def corr_ok(r: dict, cap: float, both: bool = False) -> bool:
    w, p = r.get("within"), r.get("pooled")
    if w is None or not np.isfinite(w):
        return False
    if both and (p is None or not np.isfinite(p) or abs(p) > cap):
        return False
    return bool(abs(w) <= cap)


def design_ss(df: pd.DataFrame, term: str, controls: list[str]) -> dict:
    """Within-market (expanding-past demeaned) design of ``term`` given ``controls``: the residual sum of squares of the
    demeaned term on the demeaned controls (what governs the coefficient's SE) and the within VIF."""
    cols = [term, *controls]
    d = df[["market_id", "t_row", *cols]].replace([np.inf, -np.inf], np.nan).dropna()
    if len(d) < len(cols) + 10:
        return {"n": len(d), "ss_resid": float("nan"), "vif_w": float("nan")}
    X = demean(d, cols, "market_id", "t_row", "expanding").replace([np.inf, -np.inf], np.nan).dropna()
    Z = X[controls].to_numpy() if controls else np.zeros((len(X), 0))
    xt = _partial(Z, X[term].to_numpy())
    x0 = X[term].to_numpy() - X[term].mean()
    ss, ss0 = float(xt @ xt), float(x0 @ x0)
    return {"n": int(len(X)), "ss_resid": ss, "vif_w": float(ss0 / ss) if ss > 0 else float("inf")}


def mde_class(n1: float, n2: float, sd: float, de: float, a: dict, vif: float = 1.0) -> float:
    """Planning MDE (price units) of a two-class contrast on projected effective counts (section 8 formula)."""
    if not (n1 > 0 and n2 > 0 and np.isfinite(de)):
        return float("inf")
    return a["t_sum"] * sd * math.sqrt(1.0 / n1 + 1.0 / n2) * math.sqrt(de) * a["day_factor"] * math.sqrt(max(vif, 1.0))


def mde_slope_design(ss_resid: float, scale: float, sd: float, de: float, a: dict) -> float:
    """Planning MDE per unit of the (standardised) term from the census design: t_sum x SD / sqrt(projected residual SS)
    x sqrt(DE) x day. Equals section 8's slope formula with the demeaned term's own variance made explicit (section 16)."""
    if not (ss_resid > 0 and np.isfinite(de)):
        return float("inf")
    return a["t_sum"] * sd / math.sqrt(ss_resid * scale) * math.sqrt(de) * a["day_factor"]


def mde_slope_declared(n_eff: float, sd: float, de: float, a: dict, vif: float) -> float:
    """Section 8's slope formula per SD of the term: t_sum x SD / sqrt(n_eff) x sqrt(DE) x day x sqrt(VIF_w)."""
    if not (n_eff > 0 and np.isfinite(de) and np.isfinite(vif)):
        return float("inf")
    return a["t_sum"] * sd / math.sqrt(n_eff) * math.sqrt(de) * a["day_factor"] * math.sqrt(max(vif, 1.0))


def _roots(r) -> list[Path]:
    return [Path(x) for x in (r if isinstance(r, (list, tuple)) else [r])] if r is not None else []


def _scan(work: Path, snapshot_roots, sweep_roots, spec: dict) -> tuple[dict, dict]:
    """Complete captures by slot and sweep 1 by snapshot id over several roots (the host's originals and a restore tree,
    census code check finding 1). Each root is scanned with its own cache; per slot the earliest-starting complete capture
    wins (the vendored rule), per snapshot id the first root that holds a sweep 1."""
    by_slot: dict[int, dict] = {}
    sweeps: dict[str, dict] = {}
    for i, r in enumerate(_roots(snapshot_roots)):
        for k, c in scan_captures(r, State(Path(work) / f"scan_snap{i}"), spec).items():
            if k not in by_slot or c["start"] < by_slot[k]["start"]:
                by_slot[k] = c
    for i, r in enumerate(_roots(sweep_roots)):
        for sid, v in scan_sweeps(r, State(Path(work) / f"scan_sweep{i}")).items():
            sweeps.setdefault(sid, v)
    return by_slot, sweeps


def _name_time(name: str) -> float:
    """Start time from a capture / sweep directory name ``YYYYMMDDTHHMMSSZ_...``; NaN if unparseable."""
    m = re.match(r"^(\d{8})T(\d{6})Z", name)
    if not m:
        return float("nan")
    d, t = m.groups()
    return epoch(f"{d[:4]}-{d[4:6]}-{d[6:]}T{t[:2]}:{t[2:4]}:{t[4:]}Z")


def sealed_dirs(seal: dict, sub: str) -> dict[str, list[str]]:
    """{directory name: [sealed archive paths]} for ``data-dumps/research_lab/<sub>/<dir>/<file>`` entries of a seal."""
    out: dict[str, list[str]] = {}
    pre = f"data-dumps/research_lab/{sub}/"
    for rel in seal.get("files", {}):
        if rel.startswith(pre):
            d = rel[len(pre):].split("/", 1)[0]
            out.setdefault(d, []).append(rel)
    return out


def seal_completeness(seal: dict, by_slot: dict, sweeps: dict, cap_slots: set[int], sweep_slots: set[int], spec: dict,
                      sweep_roots=None) -> dict:
    """Census code check finding 1. (a) Every sealed capture or sweep whose start falls in a needed slot must be present
    locally with every sealed file, else the census is refused ("sealed but absent"). (b) Every opened capture or sweep
    file must itself be sealed with an equal sha256 (``verify_files``). (c) Needed slots with no local capture and no
    sealed capture are genuinely missing: counted, never refused, never imputed."""
    bad: list[dict] = []
    local_caps = {c["id"]: c for c in by_slot.values()}
    allk = sorted(cap_slots | sweep_slots)
    span = (slot_time(allk[0], spec) - 3600.0, slot_time(allk[-1], spec) + 7200.0)

    def slot_for(d: str, rels: list[str]) -> int | None:
        """The seal's own slot assignment (``seal['slots'][dir]``, written by ``seal_captures``) when present, else the
        directory-name time on the grid. A sealed directory inside the needed span that maps to no slot (e.g. a sweep
        starting > 30 min after its slot) refuses the census rather than being left out of the check."""
        if d in seal.get("slots", {}):
            return slot_of(epoch(seal["slots"][d]), spec)
        t = _name_time(d)
        k = slot_of(t, spec) if np.isfinite(t) else None
        if k is None and np.isfinite(t) and span[0] <= t <= span[1]:
            bad.append({"file": rels[0], "error": "sealed directory has no slot assignment (outside the 30-min tolerance)"})
        return k

    for d, rels in sealed_dirs(seal, "snapshots").items():
        k = slot_for(d, rels)
        if k is None or k not in cap_slots:
            continue
        c = local_caps.get(d)
        if c is None:
            bad.append({"file": rels[0], "error": "sealed but absent locally (capture)"})
            continue
        for rel in rels:
            if not (Path(c["dir"]) / rel.rsplit("/", 1)[1]).exists():
                bad.append({"file": rel, "error": "sealed but absent locally"})
    for d, rels in sealed_dirs(seal, "book_sweeps").items():
        k = slot_for(d, rels)
        if k is None or k not in sweep_slots:
            continue
        home = next((Path(r) / d for r in _roots(sweep_roots) if (Path(r) / d).is_dir()), None)
        for rel in rels:
            if home is None or not (home / rel.rsplit("/", 1)[1]).exists():
                bad.append({"file": rel, "error": "sealed but absent locally"})
    files = [f for j in sorted(cap_slots) if j in by_slot for f in capture_files(by_slot[j]["dir"])]
    files += [f for j in sorted(sweep_slots) if j in by_slot and by_slot[j]["id"] in sweeps
              for f in sweep_files(sweeps[by_slot[j]["id"]]["dir"])]
    bad += verify_files(seal, files)
    sealed_slots = {slot_of(epoch(seal["slots"][d]), spec) if d in seal.get("slots", {}) else
                    (slot_of(_name_time(d), spec) if np.isfinite(_name_time(d)) else None) for d in sealed_dirs(seal, "snapshots")}
    missing = sorted(j for j in cap_slots if j not in by_slot and j not in sealed_slots)
    return {"bad": bad, "missing_slots": [iso(slot_time(j, spec)) for j in missing], "n_missing_slots": len(missing),
            "files_checked": len(files)}


def _read(work: Path, by_slot: dict, j: int, cache: dict) -> pd.DataFrame | None:
    if j not in by_slot:
        return None
    if j not in cache:
        cache[j] = read_series(work, by_slot[j]["id"])
    return cache[j]


def census_slots(days: list[str], spec: dict) -> list[int]:
    """Every grid slot whose slot time falls on one of the UTC ``days`` (present or not)."""
    out = []
    for d in days:
        t0 = epoch(f"{d}T00:00:00Z")
        k0 = slot_of(t0 + 31 * 60, spec)
        out += [k0 + i for i in range(12)]
    return sorted(out)


def fold(smid) -> np.ndarray:
    s = np.asarray(smid, float)
    return np.maximum(s, 1.0 - s)


def imbalance(dbid, dask) -> np.ndarray:
    d1, d2 = np.asarray(dbid, float), np.asarray(dask, float)
    with np.errstate(invalid="ignore", divide="ignore"):
        return np.where((d1 + d2) > 0, (d1 - d2) / (d1 + d2), np.nan)


def strata_of(df: pd.DataFrame, stratum: str | None) -> np.ndarray:
    """Market x UTC day, or the pre-declared fallback market x two-day block (spec ``perm_stratum``, fixed by the census)."""
    key = df["block"] if stratum == "block2" else df["day"]
    return (df["market_id"].astype(str) + "|" + key.astype(str)).to_numpy()


def shift_plan(codes: np.ndarray, order: np.ndarray, min_n: int) -> list[np.ndarray]:
    """Row indices of each market with >= ``min_n`` rows, sorted by ``order`` (the markets the gate shifts)."""
    out = []
    for c in np.unique(codes):
        idx = np.flatnonzero(codes == c)
        if len(idx) >= min_n:
            out.append(idx[np.argsort(order[idx], kind="mergesort")])
    return out


def offset_range(n: int) -> tuple[int, int]:
    s = max(4, math.ceil(n / 4))
    return s, n - s


def circular_shift(e: np.ndarray, plan: list[np.ndarray], rng: np.random.Generator) -> np.ndarray:
    """One draw: each planned market's residuals rotated by its own uniform offset; other rows unchanged."""
    ep = e.copy()
    for idx in plan:
        lo, hi = offset_range(len(idx))
        ep[idx] = np.roll(e[idx], int(rng.integers(lo, hi + 1)))
    return ep


def block_fl_gate(df: pd.DataFrame, y: np.ndarray, term: str, controls: list[str], *, sign: int, draws: int, seed: int,
                  min_n: int = 16, group: str = "market_id", order: str = "t_row") -> dict:
    """O's gate: as ``fl_perm_gate`` (same demeaning, same reduced-model residuals and statistic), but the null draws
    rotate each market's residual series instead of permuting residuals within strata. p_perm = (1 + #{sign * draw >=
    sign * real}) / (1 + draws) < 0.05 passes."""
    X = demean(df, [term, *controls], group, order, "expanding")
    yv = np.asarray(y, float)
    ok = np.isfinite(yv) & np.all(np.isfinite(X.to_numpy()), axis=1)
    if ok.sum() < 10:
        return {"testable": False, "passes": False, "reason": "fewer than 10 rows"}
    Z = X[controls].to_numpy()[ok] if controls else np.zeros((int(ok.sum()), 0))
    xt = _partial(Z, X[term].to_numpy()[ok])
    e = _partial(Z, yv[ok])
    sxx = float(xt @ xt)
    if sxx <= 1e-18:
        return {"testable": False, "passes": False, "reason": "no residual variation in the term"}
    real = float(xt @ e / sxx)
    codes = pd.factorize(df[group].astype(str).to_numpy()[ok])[0]
    plan = shift_plan(codes, df[order].to_numpy(float)[ok], min_n)
    shifted = int(sum(len(i) for i in plan))
    if not plan:
        return {"testable": False, "passes": False, "reason": f"no market with >= {min_n} rows", "share_rows_shifted": 0.0}
    rng = np.random.default_rng(seed)
    ge = 0
    for _ in range(draws):
        bb = float(xt @ circular_shift(e, plan, rng) / sxx)
        ge += int(sign * bb >= sign * real)
    p = (1 + ge) / (1 + draws)
    return {"testable": True, "real": real, "p_perm": p, "passes": bool(p < 0.05), "draws": draws,
            "method": "block circular-shift Freedman-Lane", "min_n": min_n, "share_rows_shifted": shifted / int(ok.sum()),
            "markets_shifted": len(plan)}


